SELECT CASE WHEN YEAR(event_time) < 2024 THEN 'before_2024' WHEN YEAR(event_time) = 2024 THEN '2024' ELSE 'after_2024' END event_cohort, SUM(duration_sec) total_duration_sec, COUNT(*) cnt, SUM(SUM(duration_sec)) OVER (ORDER BY CASE WHEN YEAR(event_time) < 2024 THEN 'before_2024' WHEN YEAR(event_time) = 2024 THEN '2024' ELSE 'after_2024' END) AS cumulative_duration_sec FROM web_events GROUP BY CASE WHEN YEAR(event_time) < 2024 THEN 'before_2024' WHEN YEAR(event_time) = 2024 THEN '2024' ELSE 'after_2024' END ORDER BY event_cohort, total_duration_sec DESC;
